        // Map exposes three Collection views instead
        Collection<Integer> vals = map.values();
        System.out.println("keySet: " + new TreeSet<>(map.keySet()));
        System.out.println("values size: " + vals.size());
        System.out.println("entries: " + map.entrySet().size());
        // Views are live: removing from the view changes the map
        map.keySet().remove("a");
        System.out.println("after view remove: " + map);
    }
}

