public class Main {
    // Counts how many nodes must be walked to reach index i in a linked list
    static int stepsToReach(int size, int i) {
        return Math.min(i, size - 1 - i); // LinkedList walks from the nearer end
    }

    public static void main(String[] args) {
        List<Integer> a = new ArrayList<>(List.of(10, 20, 30, 40, 50));
        List<Integer> l = new LinkedList<>(List.of(10, 20, 30, 40, 50));
        // Same insert in the middle gives the same result for both
        a.add(2, 99);
        l.add(2, 99);
        System.out.println("ArrayList : " + a);
        System.out.println("LinkedList: " + l);
        System.out.println("equal: " + a.equals(l));
        // get(i): ArrayList jumps straight there, LinkedList walks node by node
        int n = 1_000_000;
        System.out.println("walk steps for get(500000) in LinkedList of 1M: "
                + stepsToReach(n, 500_000));
        System.out.println("walk steps for get(500000) in ArrayList: 0 (array index)");
        // Using ArrayDeque for queue work instead of LinkedList
        Deque<Integer> q = new ArrayDeque<>();
        q.offerLast(1);
        q.offerLast(2);
        System.out.println("poll: " + q.pollFirst());
    }
}

