public class Main {
    public static void main(String[] args) {
        int[] data = {5, 3, 5, 9, 1, 3, 7};
        Set<Integer> hash = new HashSet<>();
        Set<Integer> linked = new LinkedHashSet<>();
        TreeSet<Integer> tree = new TreeSet<>();
        for (int x : data) {
            hash.add(x);
            linked.add(x);
            tree.add(x);
        }
        System.out.println("input     : " + Arrays.toString(data));
        System.out.println("HashSet   : " + hash);   // no promised order
        System.out.println("Linked    : " + linked); // insertion order, deduped
        System.out.println("TreeSet   : " + tree);   // sorted
        // TreeSet navigation: nearest values
        System.out.println("floor(6)  : " + tree.floor(6));    // greatest <= 6
        System.out.println("ceiling(6): " + tree.ceiling(6));  // smallest >= 6
        System.out.println("higher(9) : " + tree.higher(9));   // strictly greater
        System.out.println("headSet(5): " + tree.headSet(5));  // elements < 5
        System.out.println("tailSet(5): " + tree.tailSet(5));  // elements >= 5
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        // 1) Removing the first element in for-each throws CME
        List<Integer> a = new ArrayList<>(List.of(1, 2, 3, 4));
        try {
            for (Integer x : a) {
                if (x == 1) a.remove(x); // structural change bumps modCount
            }
        } catch (ConcurrentModificationException e) {
            System.out.println("remove 1: CME");
        }
        // 2) Removing the second-to-last element exits silently
        List<Integer> b = new ArrayList<>(List.of(1, 2, 3, 4));
        for (Integer x : b) {
            if (x == 3) b.remove(x); // hasNext() sees cursor == size, loop ends
        }
        System.out.println("remove 3: no exception, list = " + b);
        // 3) Safe ways
        List<Integer> c = new ArrayList<>(List.of(1, 2, 3, 4));
        Iterator<Integer> it = c.iterator();
        while (it.hasNext()) {
            if (it.next() % 2 == 0) it.remove(); // iterator's own remove
        }
        System.out.println("Iterator.remove: " + c);
        List<Integer> d = new ArrayList<>(List.of(1, 2, 3, 4));
        d.removeIf(x -> x % 2 == 0);
        System.out.println("removeIf: " + d);
    }
}

import java.util.*;

public class Main {
    static class Bad {
        final int id;
        Bad(int id) { this.id = id; }
        @Override public boolean equals(Object o) {
            return o instanceof Bad && ((Bad) o).id == id;
        } // equals overridden, hashCode NOT overridden
    }

    record Good(int id) { } // record: equals and hashCode generated together

    // The same bucket-index math HashMap uses
    static int bucket(Object k, int capacity) {
        int h = k.hashCode();
        h ^= (h >>> 16);               // spread high bits down
        return h & (capacity - 1);     // power-of-two mask instead of modulo
    }

    public static void main(String[] args) {
        Map<Bad, String> bad = new HashMap<>();
        bad.put(new Bad(1), "one");
        System.out.println("Bad lookup : " + bad.get(new Bad(1)));   // null: different hash
        Map<Good, String> good = new HashMap<>();
        good.put(new Good(1), "one");
        System.out.println("Good lookup: " + good.get(new Good(1))); // one
        System.out.println("bucket of Integer 17 in 16 slots: " + bucket(17, 16));
        System.out.println("bucket of Integer 33 in 16 slots: " + bucket(33, 16));
        // Mutating a key after insertion strands the entry
        List<Integer> key = new ArrayList<>(List.of(1));
        Map<List<Integer>, String> m = new HashMap<>();
        m.put(key, "v");
        key.add(2);
        System.out.println("after mutating key: " + m.get(key));
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        String[] words = {"to", "be", "or", "not", "to", "be"};
        Map<String, Integer> count = new TreeMap<>();
        for (String w : words) {
            count.merge(w, 1, Integer::sum); // absent -> 1, present -> old + 1
        }
        System.out.println("words: " + Arrays.toString(words));
        System.out.println("merge counts: " + count);
        // getOrDefault reads only, it never inserts
        System.out.println("getOrDefault(zzz): " + count.getOrDefault("zzz", 0)
                + ", size still " + count.size());
        // computeIfAbsent builds the list lazily, once per key
        Map<Integer, List<String>> byLen = new TreeMap<>();
        for (String w : words) {
            byLen.computeIfAbsent(w.length(), k -> new ArrayList<>()).add(w);
        }
        System.out.println("grouped by length: " + byLen);
        // putIfAbsent evaluates its value eagerly and keeps the old one
        Map<String, String> m = new HashMap<>();
        System.out.println("putIfAbsent 1st: " + m.putIfAbsent("k", "first"));
        System.out.println("putIfAbsent 2nd: " + m.putIfAbsent("k", "second"));
        // merge returning null removes the entry
        count.merge("not", 1, (o, n) -> null);
        System.out.println("after merge->null: " + count);
    }
}

