public class Main {
    record Task(String name, int priority) { }

    public static void main(String[] args) {
        PriorityQueue<Integer> min = new PriorityQueue<>(List.of(5, 1, 8, 3, 2));
        PriorityQueue<Integer> max = new PriorityQueue<>(Comparator.reverseOrder());
        max.addAll(List.of(5, 1, 8, 3, 2));
        System.out.println("peek min: " + min.peek() + ", peek max: " + max.peek());
        // toString shows heap array order, NOT sorted order
        System.out.println("min heap array: " + min);
        StringBuilder sb = new StringBuilder();
        while (!min.isEmpty()) sb.append(min.poll()).append(' '); // O(log n) each
        System.out.println("polled in order: " + sb.toString().trim());
        // Custom objects: order by priority, then name
        PriorityQueue<Task> tasks = new PriorityQueue<>(
                Comparator.comparingInt(Task::priority).thenComparing(Task::name));
        tasks.add(new Task("write", 2));
        tasks.add(new Task("test", 1));
        tasks.add(new Task("deploy", 2));
        while (!tasks.isEmpty()) System.out.println(tasks.poll());
        // (a, b) -> b - a overflows for extreme values
        int a = Integer.MIN_VALUE, b = 1;
        System.out.println("b - a overflow result: " + (b - a)
                + " vs compare: " + Integer.compare(b, a));
    }
}

