public class Main {
    public static void main(String[] args) {
        Deque<Integer> dq = new ArrayDeque<>();
        dq.push(1); dq.push(2); dq.push(3); // push = addFirst
        System.out.println("ArrayDeque as stack, iterates top-first: " + dq);
        Stack<Integer> st = new Stack<>();
        st.push(1); st.push(2); st.push(3);
        System.out.println("Stack iterates bottom-first: " + st);
        st.add(0, 99); // Stack exposes index ops: inserts BELOW the top
        System.out.println("Stack after add(0, 99): " + st);
        System.out.println("pop: " + dq.pop() + ", peek: " + dq.peek());
        // As a queue: offer at tail, poll from head
        Deque<String> q = new ArrayDeque<>();
        q.offer("a"); q.offer("b");
        System.out.println("poll: " + q.poll() + ", poll: " + q.poll()
                + ", poll on empty: " + q.poll()); // null, not an exception
        try {
            q.addFirst(null); // null is the "empty" signal, so it is banned
        } catch (NullPointerException e) {
            System.out.println("null rejected: NullPointerException");
        }
    }
}

