public class Main {
    static void tryAdd(String label, List<Integer> l) {
        try {
            l.add(4);
            System.out.println(label + ": add worked -> " + l);
        } catch (UnsupportedOperationException e) {
            System.out.println(label + ": add -> UnsupportedOperationException");
        }
    }

    public static void main(String[] args) {
        List<Integer> src = new ArrayList<>(List.of(1, 2, 3));
        List<Integer> view = Collections.unmodifiableList(src);
        List<Integer> copy = List.copyOf(src);
        src.add(100); // owner changes the original
        System.out.println("view sees change: " + view);  // [1, 2, 3, 100]
        System.out.println("copy is snapshot: " + copy);  // [1, 2, 3]
        tryAdd("unmodifiableList", view);
        tryAdd("List.of", List.of(1, 2, 3));
        Integer[] arr = {1, 2, 3};
        List<Integer> fixed = Arrays.asList(arr);
        fixed.set(0, 7); // write-through to the array
        System.out.println("array after set: " + Arrays.toString(arr));
        tryAdd("Arrays.asList", fixed);
        try {
            List.of(1, 2).contains(null);
        } catch (NullPointerException e) {
            System.out.println("List.of contains(null): NullPointerException");
        }
        int[] prim = {1, 2, 3};
        System.out.println("Arrays.asList(int[]).size(): " + Arrays.asList(prim).size());
    }
}

