public class Main {
    public static void main(String[] args) {
        // Tax bands: income threshold -> rate percent
        TreeMap<Integer, Integer> bands = new TreeMap<>();
        bands.put(0, 0);
        bands.put(10_000, 10);
        bands.put(40_000, 20);
        bands.put(90_000, 35);
        for (int income : new int[]{5_000, 10_000, 55_000, 120_000}) {
            // floorEntry: the greatest threshold <= income
            System.out.println("income " + income + " -> rate "
                    + bands.floorEntry(income).getValue() + "%");
        }
        // Time-series: events keyed by timestamp
        TreeMap<Integer, String> events = new TreeMap<>();
        for (int t : new int[]{10, 20, 30, 40, 50}) events.put(t, "e" + t);
        // Count events in [20, 40] using a live range view
        System.out.println("events in [20,40]: "
                + events.subMap(20, true, 40, true).size());
        System.out.println("first/last: " + events.firstKey() + "/" + events.lastKey());
        System.out.println("lower(30)=" + events.lowerKey(30)
                + " higher(30)=" + events.higherKey(30));
        System.out.println("descending: " + events.descendingMap().keySet());
        System.out.println("pollFirst: " + events.pollFirstEntry().getValue()
                + ", size now " + events.size());
    }
}

import java.util.*;

public class Main {
    // LRU cache: access-order LinkedHashMap + removeEldestEntry
    static class LRU<K, V> extends LinkedHashMap<K, V> {
        private final int capacity;
        LRU(int capacity) {
            super(16, 0.75f, true); // true = order by access, not insertion
            this.capacity = capacity;
        }
        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > capacity; // called after every put
        }
    }

    public static void main(String[] args) {
        LRU<String, Integer> cache = new LRU<>(3);
        cache.put("a", 1);
        cache.put("b", 2);
        cache.put("c", 3);
        System.out.println("start      : " + cache.keySet());
        cache.get("a"); // a becomes most recently used (moves to the tail)
        System.out.println("get(a)     : " + cache.keySet());
        cache.put("d", 4); // over capacity: the head (b) is evicted
        System.out.println("put(d)     : " + cache.keySet());
        System.out.println("contains b : " + cache.containsKey("b"));
        cache.put("c", 30); // overwriting also refreshes recency
        System.out.println("put(c,30)  : " + cache.keySet() + " " + cache.get("c"));
    }
}

public class Main {
    public static void main(String[] args) {
        // Simulate ArrayList growth: first add allocates 10, then 1.5x
        int capacity = 0, size = 0, resizes = 0;
        long copies = 0;
        int n = 1_000_000;
        for (int i = 0; i < n; i++) {
            if (size == capacity) {
                int newCap = capacity == 0 ? 10 : capacity + (capacity >> 1);
                copies += size; // growing copies every existing element
                capacity = newCap;
                resizes++;
            }
            size++;
        }
        System.out.println("adds: " + n);
        System.out.println("resizes: " + resizes);
        System.out.println("total elements copied: " + copies);
        // Total copy work stays a small constant times n, so cost per add is O(1)
        System.out.printf("copies per add: %.2f%n", (double) copies / n);
        System.out.println("final capacity: " + capacity);
    }
}

