import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        ConcurrentHashMap<String, Integer> counts = new ConcurrentHashMap<>();
        Map<String, Integer> unsafe = new HashMap<>();
        int threads = 4, perThread = 10_000;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        List<Future<?>> fs = new ArrayList<>();
        for (int t = 0; t < threads; t++) {
            fs.add(pool.submit(() -> {
                for (int i = 0; i < perThread; i++) {
                    counts.merge("hits", 1, Integer::sum); // atomic per key
                }
            }));
        }
        for (Future<?> f : fs) f.get();
        pool.shutdown();
        System.out.println("expected: " + (threads * perThread));
        System.out.println("ConcurrentHashMap.merge: " + counts.get("hits"));
        // Compound check-then-act is NOT atomic even on ConcurrentHashMap
        // Use putIfAbsent / computeIfAbsent instead
        ConcurrentHashMap<String, String> m = new ConcurrentHashMap<>();
        System.out.println("putIfAbsent: " + m.putIfAbsent("k", "v1"));
        System.out.println("putIfAbsent again: " + m.putIfAbsent("k", "v2"));
    }
}

