public class Main {
    static List<Integer> buggy(List<Integer> in) {
        List<Integer> l = new ArrayList<>(in);
        try {
            for (Integer x : l) if (x % 2 == 0) l.remove(x);
        } catch (ConcurrentModificationException e) {
            return List.of(-1); // marker for CME
        }
        return l;
    }

    static List<Integer> fixed(List<Integer> in) {
        List<Integer> l = new ArrayList<>(in);
        l.removeIf(x -> x % 2 == 0); // intent-revealing, O(n)
        return l;
    }

    public static void main(String[] args) {
        int[][] cases = {{}, {1, 3, 5}, {2, 4, 6}, {1, 2, 3}, {1, 3, 4}, {2, 2, 1}};
        for (int[] c : cases) {
            List<Integer> in = new ArrayList<>();
            for (int v : c) in.add(v);
            System.out.println(in + " buggy=" + buggy(in) + " fixed=" + fixed(in));
        }
        // List<Integer>.remove(int) vs remove(Object) trap
        List<Integer> l = new ArrayList<>(List.of(10, 20, 30));
        l.remove(1);                  // index overload: removes 20
        System.out.println("remove(1): " + l);
        l.remove(Integer.valueOf(10)); // object overload
        System.out.println("remove(Integer.valueOf(10)): " + l);
    }
}
